using System; using System.Collections.Generic; using System.Data.Entity; using System.Linq; using System.Reflection; using PAP.DataAccess;
namespace PAP.Generators { public abstract class GeneratorBase { public abstract string EntityName {get;} public abstract string[] Dependencies {get;} protected abstract object Build(BookStoreDBEntities db); public string Generate(){ using(var db=new BookStoreDBEntities()){ if(Count(db,EntityName)>0) throw new InvalidOperationException(EntityName+" ya contiene registros."); foreach(var dep in Dependencies){ if(Count(db,dep)==0) throw new InvalidOperationException("Primero genere datos en "+dep+"."); } var entity=Build(db); db.Entry(entity).State=EntityState.Added; db.SaveChanges(); return "Datos generados para "+EntityName; } } protected static int Count(BookStoreDBEntities db,string name){ var p=db.GetType().GetProperty(name); if(p==null)return 0; var value=p.GetValue(db,null) as System.Collections.IEnumerable; return value==null?0:value.Cast<object>().Count(); } protected static object GetSet(BookStoreDBEntities db,string name){return db.GetType().GetProperty(name).GetValue(db,null);} protected static T Make<T>(params object[] pairs) where T:class,new(){var x=new T(); for(int i=0;i<pairs.Length;i+=2){var p=typeof(T).GetProperty((string)pairs[i]); if(p!=null){var raw=pairs[i+1]; if(raw!=null){var target=Nullable.GetUnderlyingType(p.PropertyType) ?? p.PropertyType; if(!target.IsInstanceOfType(raw)) raw=Convert.ChangeType(raw,target); } p.SetValue(x,raw,null);}} return x;} protected static int FirstId(BookStoreDBEntities db,string setName){var set=GetSet(db,setName); var first=((System.Collections.IEnumerable)set).Cast<object>().FirstOrDefault(); if(first==null) throw new InvalidOperationException("No hay registros en "+setName); return (int)first.GetType().GetProperty("Id").GetValue(first,null);} } }
